// 核对 grill-first 与 our-free-model 的 GitHub 来源、OpenViking 数据位置
const r = await tools.pwsh({
  description: "核对插件来源与 openviking 数据位置",
  command: `
Write-Host '=== 插件包来源解析 ==='
foreach ($pkg in @('dsh-grill-first','dsh-our-free-model')) {
  $p = "$env:DSH_HOME\\profiles\\desktop\\node_modules\\$pkg\\package.json"
  if (Test-Path $p) {
    $j = Get-Content $p -Raw | ConvertFrom-Json
    "{0}: version={1} repository={2}" -f $pkg, $j.version, ($j.repository.url 2>$null)
  }
}
Write-Host '=== openviking 数据目录探测 ==='
foreach ($p in @("$env:DSH_HOME\\openai-gateway", "$env:DSH_HOME\\storages\\workspace.json")) {
  if (Test-Path $p) { "--- $p ---" }
}
Get-Content "$env:DSH_HOME\\storages\\workspace.json" -Raw -ErrorAction SilentlyContinue
Write-Host '=== openviking home ==='
foreach ($cand in @("$env:USERPROFILE\\.openviking", "$env:USERPROFILE\\viking")) {
  if (Test-Path $cand) { "存在: $cand"; Get-ChildItem $cand -Depth 0 | Select-Object Name | Out-String }
}
`
});
console.log(r.stdout);
